-- Foreign keys Drizzle cannot express: deferred checks (a directory moves together with its tasks in one
-- transaction) and ON DELETE SET NULL (column), which clears only the reference and never the owner (PostgreSQL 15+).
ALTER TABLE "task" ADD CONSTRAINT "task_directory_fk" FOREIGN KEY ("owner","directory_id","project_id") REFERENCES "public"."directory"("owner","id","project_id") ON DELETE NO ACTION ON UPDATE NO ACTION DEFERRABLE INITIALLY DEFERRED;--> statement-breakpoint
